    # and any input that is not a length-canonical base64url encoding.
    try:
        key = base64.b64decode(raw + "=" * (-len(raw) % 4), validate=True)
    except (ValueError, TypeError) as exc:
        raise InvalidKey("secret must be an unpadded base64url string") from exc
    if not raw.endswith(("_", "-")) and base64.b64encode(key).rstrip(b"=").decode() != raw:
        raise InvalidKey("secret must be the canonical unpadded base64url encoding")
    if len(key) < _MIN_KEY_BYTES:
        raise InvalidKey("secret must decode to at least 32 bytes")
    return key


