    # silently drops trailing bits); unpadded urlsafe b64 must round-trip.
    if base64.urlsafe_b64encode(key).rstrip(b"=").decode("ascii") != raw:
        raise InvalidKey("secret must be the canonical unpadded base64url encoding")
    if len(key) < _MIN_KEY_BYTES:
        raise InvalidKey("secret must decode to at least 32 bytes")
    return key


